local BellWheelMaker = {}
local PRODUCTS = {
    hand_bell = { name = "Ročni zvonec", brassCost = 1, time = 1, cost = 12, soundQuality = 6, description = "Majhen ročni zvonec za oltar." },
    altar_bell = { name = "Oltarni zvonec", brassCost = 2, time = 2, cost = 35, soundQuality = 9, prestige = 1, description = "Oltarni zvonec za elevacijo." },
    sacring_bell = { name = "Posvetilni zvonec", silverCost = 1, brassCost = 1, time = 3, cost = 80, soundQuality = 12, prestige = 3, description = "Posvetilni zvonec z jasnim tonom." },
    ship_bell = { name = "Ladjani zvonec", brassCost = 2, ironCost = 1, time = 4, cost = 180, soundQuality = 15, prestige = 5, description = "Ladjani zvonec z močnim zvokom." },
    silver_hand_bell = { name = "Srebrni ročni zvonec", silverCost = 2, time = 6, cost = 380, soundQuality = 20, prestige = 10, happiness = 1, description = "Srebrni ročni zvonec za slovesnosti." },
    royal_carillon_bell = { name = "Kraljevski kariljonski zvonec", goldCost = 2, silverCost = 2, brassCost = 2, time = 11, cost = 1500, soundQuality = 35, prestige = 38, happiness = 7, description = "Veliki kraljevski kariljonski zvonec z zlatim in srebrnim Tonom." },
}
local BUILDINGS = {
    workshop = { name = "Zvončarska delavnica", cost = { gold = 250, wood = 110 }, upkeep = 6, qualityBonus = 5 },
    forge = { name = "Zvončarska kovačija", cost = { gold = 800, wood = 220, stone = 200, brass = 6 }, upkeep = 20, qualityBonus = 18 },
    tuning_room = { name = "Naglasilnica", cost = { gold = 1700, wood = 280, stone = 350, silver = 25, brass = 8 }, upkeep = 40, qualityBonus = 30 },
    royal_bell_atelier = { name = "Kraljevski atelje zvoncev", cost = { gold = 6500, wood = 500, stone = 700, gold = 50, silver = 30 }, upkeep = 120, qualityBonus = 55, prestigeBonus = 30 },
}
BellWheelMaker.brassStock = 12; BellWheelMaker.ironStock = 10; BellWheelMaker.silverStock = 8; BellWheelMaker.goldStock = 6
BellWheelMaker.productStock = {}; BellWheelMaker.buildings = {}; BellWheelMaker.maker = nil; BellWheelMaker.activeMaking = {}; BellWheelMaker.totalProducts = 0; BellWheelMaker.dayTimer = 0
function BellWheelMaker.init() BellWheelMaker.brassStock=12; BellWheelMaker.ironStock=10; BellWheelMaker.silverStock=8; BellWheelMaker.goldStock=6; BellWheelMaker.productStock={}; BellWheelMaker.buildings={}; BellWheelMaker.maker=nil; BellWheelMaker.activeMaking={}; BellWheelMaker.totalProducts=0; BellWheelMaker.dayTimer=0; print("[BellWheelMaker] Royal Bell Wheel Maker System initialized (6 products, 4 buildings)") end
function BellWheelMaker.hireMaker(n,s) s=s or math.random(50,90); local c=460+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BellWheelMaker.maker={name=n or ("Zvončar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zvončar najet: %s (spretnost: %d)",BellWheelMaker.maker.name,s),"success") end; return true end
function BellWheelMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BellWheelMaker.build(id) local ok,e=BellWheelMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BellWheelMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BellWheelMaker.getQualityBonus() local b=0; for _,bd in ipairs(BellWheelMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BellWheelMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.brassCost and BellWheelMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.ironCost and BellWheelMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.silverCost and BellWheelMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BellWheelMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if #BellWheelMaker.buildings==0 then return false,"Potrebna delavnica" end; if not BellWheelMaker.maker then return false,"Potreben zvončar" end; return true end
function BellWheelMaker.make(pt,qty) qty=qty or 5; local ok,e=BellWheelMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.brassCost then BellWheelMaker.brassStock=BellWheelMaker.brassStock-d.brassCost*qty end; if d.ironCost then BellWheelMaker.ironStock=BellWheelMaker.ironStock-d.ironCost*qty end; if d.silverCost then BellWheelMaker.silverStock=BellWheelMaker.silverStock-d.silverCost*qty end; if d.goldCost then BellWheelMaker.goldStock=BellWheelMaker.goldStock-d.goldCost*qty end; local t=d.time; if BellWheelMaker.maker then t=math.max(1,t-math.floor(BellWheelMaker.maker.skill/12)) end; table.insert(BellWheelMaker.activeMaking,{id="bellwheel_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,soundQuality=d.soundQuality or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BellWheelMaker.completeMaking(m) local q=1.0+(BellWheelMaker.getQualityBonus()/100); if BellWheelMaker.maker then q=q+(BellWheelMaker.maker.skill/180) end; q=math.min(2.0,q); BellWheelMaker.productStock[m.productType]=(BellWheelMaker.productStock[m.productType] or 0)+m.quantity; BellWheelMaker.totalProducts=BellWheelMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BellWheelMaker.maker then BellWheelMaker.maker.itemsMade=BellWheelMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then BellWheelMaker.maker.skill=math.min(100,BellWheelMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zvončki izdelani: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"bellwheel.completed",{productName=m.productName,soundQuality=m.soundQuality}) end end
function BellWheelMaker.update(dt) if not _G.state then return end; BellWheelMaker.dayTimer=BellWheelMaker.dayTimer+dt; if BellWheelMaker.dayTimer>=30 then BellWheelMaker.dayTimer=0; for i=#BellWheelMaker.activeMaking,1,-1 do local m=BellWheelMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BellWheelMaker.completeMaking(m); table.remove(BellWheelMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BellWheelMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BellWheelMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BellWheelMaker.getStats() return {brassStock=BellWheelMaker.brassStock,ironStock=BellWheelMaker.ironStock,silverStock=BellWheelMaker.silverStock,goldStock=BellWheelMaker.goldStock,productStock=BellWheelMaker.productStock,numBuildings=#BellWheelMaker.buildings,hasMaker=BellWheelMaker.maker~=nil,makerName=BellWheelMaker.maker and BellWheelMaker.maker.name or "—",makerSkill=BellWheelMaker.maker and BellWheelMaker.maker.skill or 0,activeMaking=#BellWheelMaker.activeMaking,totalProducts=BellWheelMaker.totalProducts} end
return BellWheelMaker
